import sqlite3


class Counted:
    """Counts the calls the program makes to execute and executemany."""

    def __init__(self, conn):
        self.conn = conn
        self.calls = 0

    def execute(self, sql, params=()):
        self.calls += 1
        return self.conn.execute(sql, params)

    def executemany(self, sql, rows):
        self.calls += 1
        return self.conn.executemany(sql, rows)


conn = sqlite3.connect(":memory:")
conn.executescript("""
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE orders (id INTEGER PRIMARY KEY, cust_id INTEGER, total INTEGER);
INSERT INTO customers VALUES (1, 'Ann'), (2, 'Bo'), (3, 'Cy');
INSERT INTO orders VALUES (10, 1, 30), (11, 1, 80), (12, 3, 20);
""")
db = Counted(conn)
customers = db.execute("SELECT id FROM customers ORDER BY id").fetchall()
looped = []
for (cid,) in customers:
    looped += db.execute("SELECT id FROM orders WHERE cust_id = ? ORDER BY id", (cid,)).fetchall()
n_loop = db.calls
db.calls = 0
joined = db.execute(
    "SELECT o.id FROM customers c JOIN orders o ON o.cust_id = c.id ORDER BY o.id"
).fetchall()
print(n_loop, db.calls, looped == joined)
